int main(void) {
    int seconds = 3725;
    int hours = seconds / 3600;
    int minutes = (seconds % 3600) / 60;
    int secs = seconds % 60;
    printf("%d seconds = %02d:%02d:%02d\n", seconds, hours, minutes, secs);
    return 0;
}

